ID_11=$(create /networkServices 'fws-SMTP' "$OUT/11.json" 11)
cat > "$OUT/12.json" <<FWSHIFT_JSON
{"name": "fws-Update-Site.1.alm", "type": "DSTN_FQDN", "addresses": ["updates.example.com"], "description": "FWShift"}
