# Firewall filtering rules, from order 1 on, in the order of the converted policy.
cat > "$OUT/18.json" <<FWSHIFT_JSON
{"name": "fws-Block Bad", "order": 1, "rank": 7, "action": "BLOCK_DROP", "state": "ENABLED", "locations": [{"id": ${ID_1}}, {"id": ${ID_2}}], "destAddresses": ["192.0.2.66", "203.0.113.0/25"]}
