{"name": "fws-Admin SSH", "order": 2, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}], "srcIpGroups": [{"id": ${ID_3}}], "nwServices": [{"id": ${ID_4}}]}
