cat > "$OUT/20.json" <<FWSHIFT_JSON
{"name": "fws-Web Out", "order": 3, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_1}}, {"id": ${ID_2}}, {"id": ${ID_5}}], "nwServices": [{"id": ${ID_6}}]}
