cat > "$OUT/22.json" <<FWSHIFT_JSON
{"name": "fws-Mail In", "order": 5, "rank": 7, "action": "ALLOW", "state": "ENABLED", "locations": [{"id": ${ID_7}}], "destIpGroups": [{"id": ${ID_10}}], "nwServices": [{"id": ${ID_11}}]}
