ID_22=$(create /firewallFilteringRules 'fws-Mail In' "$OUT/22.json" 22)
cat > "$OUT/23.json" <<FWSHIFT_JSON
{"name": "fws-DMZ Updates", "order": 6, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_5}}], "destIpGroups": [{"id": ${ID_12}}], "nwServices": [{"id": ${ID_9}}]}
