{"name": "fws-Staff Only", "order": 8, "rank": 7, "action": "ALLOW", "state": "DISABLED", "description": "FWSHIFT inactive, see the report.", "locations": [{"id": ${ID_1}}], "destIpGroups": [{"id": ${ID_14}}], "nwServices": [{"id": ${ID_15}}]}
