{"name": "fws-block the rest", "order": 11, "rank": 7, "action": "BLOCK_DROP", "state": "DISABLED", "description": "FWSHIFT: what the converted policy does not allow. Enable after looking at the rules below"}
FWSHIFT_JSON
ID_28=$(create /firewallFilteringRules 'fws-block the rest' "$OUT/28.json" 28)
echo "done: nothing is active until the changes are activated (POST /status/activate)" >&2
